import React, { useState, useRef } from "react";
import cv from "@techstark/opencv-js";
import { Tensor, InferenceSession } from "onnxruntime-web";
import Loader from "./components/loader";
import { detectImage } from "./utils/detect";
import { cardDatabase } from "./cardData";
import "./style/App.css";
import { pipeline } from '@xenova/transformers';

const App = () => {
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState({ text: "Loading OpenCV.js", progress: null });
  const [image, setImage] = useState(null);
  const [matchedCards, setMatchedCards] = useState([]);
  const [clipModel, setClipModel] = useState(null);
  const [clipReady, setClipReady] = useState(false);
  const inputImage = useRef(null);
  const imageRef = useRef(null);
  const canvasRef = useRef(null);

  // configs
  const modelName = "best_model_1_model_v3_epochs25_batch8_lr001.onnx";
  const modelInputShape = [1, 3, 640, 640];
  const topk = 100;
  const iouThreshold = 0.45;
  const scoreThreshold = 0.25;

  // 余弦相似度计算
  const cosineSimilarity = (vecA, vecB) => {
    let dotProduct = 0;
    let magnitudeA = 0;
    let magnitudeB = 0;
    for (let i = 0; i < vecA.length; i++) {
      dotProduct += vecA[i] * vecB[i];
      magnitudeA += vecA[i] * vecA[i];
      magnitudeB += vecB[i] * vecB[i];
    }
    magnitudeA = Math.sqrt(magnitudeA);
    magnitudeB = Math.sqrt(magnitudeB);
    return dotProduct / (magnitudeA * magnitudeB);
  };

  // 初始化 CLIP 模型
  const initCLIP = async () => {
    try {
      console.log("Loading CLIP model...");
      const extractor = await pipeline('feature-extraction', 'Xenova/clip-vit-base-patch32', { 
        quantized: true 
      });
      setClipModel(extractor);
      setClipReady(true);
      console.log("CLIP model ready");
    } catch (err) {
      console.error("CLIP load failed:", err);
      setClipReady(false);
    }
  };

  // 处理检测到的物体 - 使用 CLIP 匹配
  const handleObjectDetected = async (category, croppedImage, confidence) => {
    console.log(`检测到物体: ${category}, 置信度: ${confidence}`);
    
    // Fallback: CLIP 未就绪时使用模拟匹配
    if (!clipReady || !clipModel) {
      console.log("CLIP not ready, using fallback");
      const relevantCards = cardDatabase.filter(card => card.category === category);
      if (relevantCards.length > 0) {
        const existingIds = matchedCards.map(c => c.id);
        const availableCards = relevantCards.filter(c => !existingIds.includes(c.id));
        if (availableCards.length > 0) {
          setMatchedCards(prev => [...prev, { ...availableCards[0] }]);
        }
      }
      return;
    }
    
    try {
      // 筛选同类别的卡片
      const relevantCards = cardDatabase.filter(card => card.category === category);
      if (relevantCards.length === 0) return;
      
      // 获取卡片文本
      const cardTexts = relevantCards.map(card => card.text);
      
      // 使用 CLIP 计算图像特征
      const imageFeature = await clipModel(croppedImage, { pooling: 'mean', normalize: true });
      
      // 计算文本特征
      const textFeatures = await clipModel(cardTexts, { pooling: 'mean', normalize: true });
      
      // 计算相似度，找最匹配的卡片
      let maxSimilarity = -1;
      let bestMatch = null;
      const dim = imageFeature.data.length;
      
      for (let i = 0; i < relevantCards.length; i++) {
        const start = i * dim;
        const textFeature = textFeatures.data.slice(start, start + dim);
        const similarity = cosineSimilarity(imageFeature.data, textFeature);
        console.log(`卡片 ${relevantCards[i].text} 相似度: ${similarity}`);
        if (similarity > maxSimilarity) {
          maxSimilarity = similarity;
          bestMatch = relevantCards[i];
        }
      }
      
      if (bestMatch && maxSimilarity > 0.15) {
        setMatchedCards(prev => {
          const exists = prev.some(card => card.id === bestMatch.id);
          if (exists) return prev;
          return [...prev, { ...bestMatch }];
        });
        console.log(`匹配到卡片: ${bestMatch.text}, 相似度: ${maxSimilarity}`);
      }
    } catch (err) {
      console.error("CLIP matching failed:", err);
      // Fallback: 使用模拟匹配
      const relevantCards = cardDatabase.filter(card => card.category === category);
      if (relevantCards.length > 0) {
        const existingIds = matchedCards.map(c => c.id);
        const availableCards = relevantCards.filter(c => !existingIds.includes(c.id));
        if (availableCards.length > 0) {
          setMatchedCards(prev => [...prev, { ...availableCards[0] }]);
        }
      }
    }
  };

  // wait until opencv.js initialized
  cv["onRuntimeInitialized"] = async () => {
    // 初始化 CLIP
    await initCLIP();
    
    setLoading({ text: "Loading model...", progress: null });
    const yolov8 = await InferenceSession.create(modelName);

    setLoading({ text: "Warming up nms...", progress: null });
    const nms = await InferenceSession.create('./nms-yolov8.onnx');

    setLoading({ text: "Warming up mask...", progress: null });
    const mask = await InferenceSession.create('./mask-yolov8-seg.onnx');

    setLoading({ text: "Warming up model...", progress: null });
    const tensor = new Tensor(
      "float32",
      new Float32Array(modelInputShape.reduce((a, b) => a * b)),
      modelInputShape
    );
    await yolov8.run({ images: tensor });

    setSession({ net: yolov8, nms: nms, mask: mask });
    setLoading(null);
  };

  return (
    <div className="App">
      {/* 右上角名字 */}
      <div style={{
        position: 'fixed',
        top: '20px',
        right: '30px',
        zIndex: 1000,
        fontSize: '18px',
        fontWeight: 'bold',
        color: '#333',
        backgroundColor: '#f0f0f0',
        padding: '8px 16px',
        borderRadius: '20px',
        boxShadow: '0 2px 5px rgba(0,0,0,0.1)',
        fontFamily: 'Arial, sans-serif'
      }}>
        ду линьсянь
      </div>

      {loading && (
        <Loader>
          {loading.progress ? `${loading.text} - ${loading.progress}%` : loading.text}
        </Loader>
      )}
      
      <div className="header">
        <h1>YOLOv8 Object Segmentation App</h1>
        <p>
          YOLOv8 object detection application live on browser powered by{" "}
          <code>onnxruntime-web</code>
        </p>
        <p>
          Serving : <code className="code">{modelName}</code>
        </p>
      </div>

      <div className="content">
        <img
          ref={imageRef}
          src="#"
          alt=""
          style={{ display: image ? "block" : "none" }}
          onLoad={() => {
            if (session) {
              detectImage(
                imageRef.current,
                canvasRef.current,
                session,
                topk,
                iouThreshold,
                scoreThreshold,
                modelInputShape,
                handleObjectDetected
              );
            }
          }}
        />
        <canvas
          id="canvas"
          width={modelInputShape[2]}
          height={modelInputShape[3]}
          ref={canvasRef}
        />
      </div>

      {/* 按钮容器 */}
      <div className="btn-container">
        <button onClick={() => inputImage.current.click()}>
          📁 Open local image
        </button>
        {image && (
          <button
            onClick={() => {
              inputImage.current.value = "";
              imageRef.current.src = "#";
              URL.revokeObjectURL(image);
              setImage(null);
              setMatchedCards([]);
            }}
          >
            ❌ Close image
          </button>
        )}
      </div>

      {/* 文件上传 input */}
      <input
        type="file"
        ref={inputImage}
        accept="image/*"
        onChange={(e) => {
          if (image) {
            URL.revokeObjectURL(image);
            setImage(null);
            setMatchedCards([]);
          }
          const url = URL.createObjectURL(e.target.files[0]);
          imageRef.current.src = url;
          setImage(url);
        }}
      />

      {/* 卡片列表区域 */}
      <div className="card-list-container">
        <h3>✨ 匹配到的卡片 ✨</h3>
        <div className="card-list">
          {matchedCards.length === 0 ? (
            <p className="no-cards">暂无匹配卡片，请上传图片</p>
          ) : (
            matchedCards.map((card, idx) => (
              <div key={idx} className="card">
                <div className="card-category">
                  {card.category === 'lichen' ? 'Лишайник' : 
                   card.category === 'moss' ? 'Мох' : 'Папоротник'}
                </div>
                <div className="card-text">{card.textRu || card.text}</div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default App;