import cv from "@techstark/opencv-js";
import { Tensor } from "onnxruntime-web";
import { renderBoxes, Colors } from "./renderBox";
import labels from "./labels.json";

const colors = new Colors();
const numClass = labels.length;

/**
 * Detect Image
 * @param {HTMLImageElement} image Image to detect
 * @param {HTMLCanvasElement} canvas canvas to draw boxes
 * @param {ort.InferenceSession} session YOLOv8 onnxruntime session
 * @param {Number} topk Integer representing the maximum number of boxes to be selected per class
 * @param {Number} iouThreshold Float representing the threshold for deciding whether boxes overlap too much with respect to IOU
 * @param {Number} scoreThreshold Float representing the threshold for deciding when to remove boxes based on score
 * @param {Number[]} inputShape model input shape. Normally in YOLO model [batch, channels, width, height]
 * @param {Function} onObjectDetected Callback function when object detected (category, croppedImage, confidence)
 */
export const detectImage = async (
  image,
  canvas,
  session,
  topk,
  iouThreshold,
  scoreThreshold,
  inputShape,
  onObjectDetected = null
) => {
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);

  const [modelWidth, modelHeight] = inputShape.slice(2);
  const maxSize = Math.max(modelWidth, modelHeight);
  const [input, xRatio, yRatio] = preprocessing(image, modelWidth, modelHeight);

  const tensor = new Tensor("float32", input.data32F, inputShape);
  const config = new Tensor(
    "float32",
    new Float32Array([
      numClass,
      topk,
      iouThreshold,
      scoreThreshold,
    ])
  );
  
  const { output0, output1 } = await session.net.run({ images: tensor });
  const { selected } = await session.nms.run({ detection: output0, config: config });

  const boxes = [];
  let overlay = new Tensor("uint8", new Uint8Array(modelHeight * modelWidth * 4), [
    modelHeight,
    modelWidth,
    4,
  ]);

  // looping through output
  for (let idx = 0; idx < selected.dims[1]; idx++) {
    const data = selected.data.slice(idx * selected.dims[2], (idx + 1) * selected.dims[2]);
    let box = data.slice(0, 4);
    const scores = data.slice(4, 4 + numClass);
    const score = Math.max(...scores);
    const label = scores.indexOf(score);
    const color = colors.get(label);
    const className = labels[label];

    box = overflowBoxes(
      [
        box[0] - 0.5 * box[2],
        box[1] - 0.5 * box[3],
        box[2],
        box[3],
      ],
      maxSize
    );

    const [x, y, w, h] = overflowBoxes(
      [
        Math.floor(box[0] * xRatio),
        Math.floor(box[1] * yRatio),
        Math.floor(box[2] * xRatio),
        Math.floor(box[3] * yRatio),
      ],
      maxSize
    );

    boxes.push({
      label: className,
      probability: score,
      color: color,
      bounding: [x, y, w, h],
    });

    // 回调函数：将检测到的物体裁剪并传递给 App
    if (onObjectDetected && score > scoreThreshold) {
      // 类别映射
      let category = '';
      const classNameLower = className.toLowerCase();
      if (classNameLower.includes('лишайник') || classNameLower === 'lichen') {
        category = 'lichen';
      } else if (classNameLower.includes('мох') || classNameLower === 'moss') {
        category = 'moss';
      } else if (classNameLower.includes('папоротник') || classNameLower === 'fern') {
        category = 'fern';
      }
      
      if (category) {
        try {
          // 计算缩放比例
          const scaleX = image.naturalWidth / image.clientWidth;
          const scaleY = image.naturalHeight / image.clientHeight;
          const cropX = x * scaleX;
          const cropY = y * scaleY;
          const cropW = w * scaleX;
          const cropH = h * scaleY;
          
          // 创建临时 canvas 裁剪图像
          const tempCanvas = document.createElement('canvas');
          tempCanvas.width = cropW;
          tempCanvas.height = cropH;
          const tempCtx = tempCanvas.getContext('2d');
          tempCtx.drawImage(image, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);
          
          // 转换为 Image 对象并回调
          tempCanvas.toBlob((blob) => {
            if (blob) {
              const croppedImg = new Image();
              croppedImg.src = URL.createObjectURL(blob);
              croppedImg.onload = () => {
                onObjectDetected(category, croppedImg, score);
                URL.revokeObjectURL(croppedImg.src);
              };
            }
          });
        } catch (err) {
          console.error("裁剪失败:", err);
        }
      }
    }

    const mask = new Tensor(
      "float32",
      new Float32Array([
        ...box,
        ...data.slice(4 + numClass),
      ])
    );
    const maskConfig = new Tensor(
      "float32",
      new Float32Array([
        maxSize,
        x,
        y,
        w,
        h,
        ...Colors.hexToRgba(color, 120),
      ])
    );
    const { mask_filter } = await session.mask.run({
      detection: mask,
      mask: output1,
      config: maskConfig,
      overlay: overlay,
    });
    overlay = mask_filter;
  }

  const mask_img = new ImageData(new Uint8ClampedArray(overlay.data), modelHeight, modelWidth);
  ctx.putImageData(mask_img, 0, 0);
  renderBoxes(ctx, boxes);
  input.delete();
};

/**
 * Preprocessing image
 * @param {HTMLImageElement} source image source
 * @param {Number} modelWidth model input width
 * @param {Number} modelHeight model input height
 * @param {Number} stride model stride
 * @return preprocessed image and configs
 */
const preprocessing = (source, modelWidth, modelHeight, stride = 32) => {
  const mat = cv.imread(source);
  const matC3 = new cv.Mat(mat.rows, mat.cols, cv.CV_8UC3);
  cv.cvtColor(mat, matC3, cv.COLOR_RGBA2BGR);

  let [w, h] = divStride(stride, matC3.cols, matC3.rows);
  cv.resize(matC3, matC3, new cv.Size(w, h));

  const maxSize = Math.max(matC3.rows, matC3.cols);
  const xPad = maxSize - matC3.cols;
  const xRatio = maxSize / matC3.cols;
  const yPad = maxSize - matC3.rows;
  const yRatio = maxSize / matC3.rows;
  const matPad = new cv.Mat();
  cv.copyMakeBorder(matC3, matPad, 0, yPad, 0, xPad, cv.BORDER_CONSTANT);

  const input = cv.blobFromImage(
    matPad,
    1 / 255.0,
    new cv.Size(modelWidth, modelHeight),
    new cv.Scalar(0, 0, 0),
    true,
    false
  );

  mat.delete();
  matC3.delete();
  matPad.delete();

  return [input, xRatio, yRatio];
};

/**
 * Get divisible image size by stride
 * @param {Number} stride
 * @param {Number} width
 * @param {Number} height
 * @returns {Number[2]} image size [w, h]
 */
const divStride = (stride, width, height) => {
  if (width % stride !== 0) {
    if (width % stride >= stride / 2) width = (Math.floor(width / stride) + 1) * stride;
    else width = Math.floor(width / stride) * stride;
  }
  if (height % stride !== 0) {
    if (height % stride >= stride / 2) height = (Math.floor(height / stride) + 1) * stride;
    else height = Math.floor(height / stride) * stride;
  }
  return [width, height];
};

/**
 * Handle overflow boxes based on maxSize
 * @param {Number[4]} box box in [x, y, w, h] format
 * @param {Number} maxSize
 * @returns non overflow boxes
 */
const overflowBoxes = (box, maxSize) => {
  box[0] = box[0] >= 0 ? box[0] : 0;
  box[1] = box[1] >= 0 ? box[1] : 0;
  box[2] = box[0] + box[2] <= maxSize ? box[2] : maxSize - box[0];
  box[3] = box[1] + box[3] <= maxSize ? box[3] : maxSize - box[1];
  return box;
};